@import "tailwindcss";

@theme {
  --color-mocha-rosewater: #f5e0dc;
  --color-mocha-flamingo: #f2cdcd;
  --color-mocha-pink: #f5c2e7;
  --color-mocha-mauve: #cba6f7;
  --color-mocha-red: #f38ba8;
  --color-mocha-maroon: #eba0ac;
  --color-mocha-peach: #fab387;
  --color-mocha-yellow: #f9e2af;
  --color-mocha-green: #a6e3a1;
  --color-mocha-teal: #94e2d5;
  --color-mocha-sky: #89dceb;
  --color-mocha-sapphire: #74c7ec;
  --color-mocha-blue: #89b4fa;
  --color-mocha-lavender: #b4befe;
  --color-mocha-text: #cdd6f4;
  --color-mocha-subtext1: #bac2de;
  --color-mocha-subtext0: #a6adc8;
  --color-mocha-overlay2: #9399b2;
  --color-mocha-overlay1: #7f849c;
  --color-mocha-overlay0: #6c7086;
  --color-mocha-surface2: #585b70;
  --color-mocha-surface1: #45475a;
  --color-mocha-surface0: #313244;
  --color-mocha-base: #1e1e2e;
  --color-mocha-mantle: #181825;
  --color-mocha-crust: #11111b;

  --color-background: var(--color-mocha-base);
  --color-foreground: var(--color-mocha-text);
}

:root {
  --background: #1e1e2e;
  --foreground: #cdd6f4;
}

body {
  background-color: var(--background);
  color: var(--foreground);
}

export interface Model {
  id: string;
  name: string;
  description?: string;
  pricing?: {
    prompt: string;
    completion: string;
  };
}

export interface Settings {
  selectedModels: string[];
  globalSystemPrompt: string;
  globalTemperature: number;
  globalThinkingEnabled: boolean;
  globalThinkingBudget: number;
  modelOverrides: Record<string, ModelOverride>;
}

export interface ModelOverride {
  systemPrompt?: string;
  temperature?: number;
  thinkingEnabled?: boolean;
  thinkingBudget?: number;
}

export interface Message {
  role: 'user' | 'assistant' | 'system';
  content: string;
}

export interface Conversation {
  id: string;
  timestamp: string;
  prompt: string;
  responses: Record<string, ModelResponse>;
}

export interface ModelResponse {
  modelId: string;
  content: string;
  duration: number; // in ms
  tps: number;
  tokenCount: number;
  error?: string;
  rawResponse?: any;
}

import { Model } from './types';

export async function fetchFreeModels(): Promise<Model[]> {
  try {
    const response = await fetch('https://openrouter.ai/api/v1/models', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${process.env.OPENROUTER_API_KEY}`,
        'HTTP-Referer': 'http://localhost:3000',
        'X-Title': 'Free LLM Evaluator',
      },
    });

    if (!response.ok) {
      throw new Error(`Failed to fetch models: ${response.statusText}`);
    }

    const data = await response.json();
    const models: any[] = data.data;

    // Filter for models with "free" in the name or slug
    return models
      .filter((model) => 
        model.name.toLowerCase().includes('free') || 
        model.id.toLowerCase().includes('free')
      )
      .map((model) => ({
        id: model.id,
        name: model.name,
        description: model.description,
        pricing: model.pricing,
      }));
  } catch (error) {
    console.error('Error fetching models:', error);
    return [];
  }
}

import fs from 'fs/promises';
import path from 'path';
import { Settings, Conversation } from './types';

const DATA_DIR = path.join(process.cwd(), 'data');
const SETTINGS_FILE = path.join(DATA_DIR, 'settings.json');
const CONVERSATIONS_FILE = path.join(DATA_DIR, 'conversations.json');

const DEFAULT_SETTINGS: Settings = {
  selectedModels: [],
  globalSystemPrompt: 'You are a helpful assistant.',
  globalTemperature: 0.7,
  globalThinkingEnabled: false,
  globalThinkingBudget: 1024,
  modelOverrides: {},
};

async function ensureDataDir() {
  try {
    await fs.mkdir(DATA_DIR, { recursive: true });
  } catch (error) {
    // Ignore if directory already exists
  }
}

export async function getSettings(): Promise<Settings> {
  await ensureDataDir();
  try {
    const data = await fs.readFile(SETTINGS_FILE, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    return DEFAULT_SETTINGS;
  }
}

export async function saveSettings(settings: Settings): Promise<void> {
  await ensureDataDir();
  await fs.writeFile(SETTINGS_FILE, JSON.stringify(settings, null, 2));
}

export async function getConversations(): Promise<Conversation[]> {
  await ensureDataDir();
  try {
    const data = await fs.readFile(CONVERSATIONS_FILE, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    return [];
  }
}

export async function saveConversation(conversation: Conversation): Promise<void> {
  await ensureDataDir();
  const conversations = await getConversations();
  conversations.push(conversation);
  await fs.writeFile(CONVERSATIONS_FILE, JSON.stringify(conversations, null, 2));
}

'use server';

import { fetchFreeModels } from '@/lib/openrouter';
import { getSettings, saveSettings } from '@/lib/storage';
import { Settings, Model } from '@/lib/types';

export async function getModelsAction(): Promise<Model[]> {
  return await fetchFreeModels();
}

export async function getSettingsAction(): Promise<Settings> {
  return await getSettings();
}

export async function saveSettingsAction(settings: Settings): Promise<void> {
