}

import React from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg';
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = 'primary', size = 'md', ...props }, ref) => {
    const variants = {
      primary: 'bg-mocha-blue text-mocha-base hover:bg-mocha-lavender',
      secondary: 'bg-mocha-surface1 text-mocha-text hover:bg-mocha-surface2',
      ghost: 'bg-transparent text-mocha-text hover:bg-mocha-surface0',
      danger: 'bg-mocha-red text-mocha-base hover:bg-mocha-maroon',
    };

    const sizes = {
      sm: 'px-2 py-1 text-sm',
      md: 'px-4 py-2',
      lg: 'px-6 py-3 text-lg',
    };

    return (
      <button
        ref={ref}
        className={cn(
          'rounded-md font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed',
          variants[variant],
          sizes[size],
          className
        )}
        {...props}
      />
    );
  }
);

Button.displayName = 'Button';

'use client';

import React from 'react';
import { Model } from '@/lib/types';
import { Button } from './ui/Button';
import { Check, Info } from 'lucide-react';

interface ModelSelectorProps {
  models: Model[];
  selectedModelIds: string[];
  onToggleModel: (modelId: string) => void;
}

export const ModelSelector: React.FC<ModelSelectorProps> = ({
  models,
  selectedModelIds,
  onToggleModel,
}) => {
  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold text-mocha-lavender">Free Models</h2>
        <span className="text-sm text-mocha-subtext0">
          {selectedModelIds.length} / 5 selected
        </span>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
        {models.map((model) => {
          const isSelected = selectedModelIds.includes(model.id);
          const isDisabled = !isSelected && selectedModelIds.length >= 5;

          return (
            <div
              key={model.id}
              className={cn(
                'p-4 rounded-lg border transition-all cursor-pointer relative group',
                isSelected
                  ? 'border-mocha-blue bg-mocha-surface0'
                  : 'border-mocha-surface1 bg-mocha-mantle hover:border-mocha-overlay0',
                isDisabled && 'opacity-50 cursor-not-allowed'
              )}
              onClick={() => !isDisabled && onToggleModel(model.id)}
            >
              <div className="flex items-start justify-between">
                <div>
                  <h3 className="font-semibold text-mocha-text">{model.name}</h3>
                  <p className="text-xs text-mocha-subtext0 truncate max-w-[200px]">
                    {model.id}
                  </p>
                </div>
                {isSelected && (
                  <Check className="w-5 h-5 text-mocha-blue" />
                )}
              </div>

              {model.description && (
                <div className="mt-2 text-xs text-mocha-subtext1 line-clamp-2">
                  {model.description}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

// Helper for class names since I didn't export cn from Button.tsx
