          <section>
            <label className="block text-sm font-medium text-mocha-subtext1 mb-2">
              Temperature ({settings.globalTemperature})
            </label>
            <input
              type="range"
              min="0"
              max="2"
              step="0.1"
              className="w-full accent-mocha-blue"
