import { Message, ModelOverride, Settings } from './types';

export interface StreamChunk {
  modelId: string;
  content?: string;
  error?: string;
  isDone: boolean;
  metrics?: {
    duration: number;
    tokenCount: number;
    tps: number;
  };
}

export async function* evaluateModelStream(
  modelId: string,
  messages: Message[],
  settings: Settings
): AsyncGenerator<StreamChunk> {
  const override = settings.modelOverrides[modelId] || {};
  const systemPrompt = override.systemPrompt || settings.globalSystemPrompt;
  const temperature = override.temperature ?? settings.globalTemperature;
  const thinkingEnabled = override.thinkingEnabled ?? settings.globalThinkingEnabled;
  const thinkingBudget = override.thinkingBudget ?? settings.globalThinkingBudget;

  const fullMessages = [
    { role: 'system', content: systemPrompt },
    ...messages,
  ];

  const startTime = Date.now();
  let tokenCount = 0;
  let fullContent = '';

  try {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${process.env.OPENROUTER_API_KEY}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'http://localhost:3000',
        'X-Title': 'Free LLM Evaluator',
      },
      body: JSON.stringify({
        model: modelId,
        messages: fullMessages,
        temperature,
        stream: true,
        ...(thinkingEnabled && {
          include_reasoning: true,
          thinking: {
            type: 'enabled',
            budget_tokens: thinkingBudget,
          },
        }),
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`OpenRouter API error: ${response.status} ${errorText}`);
    }

    const reader = response.body?.getReader();
    if (!reader) throw new Error('No response body');

    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (line.trim() === '') continue;
        if (line.startsWith('data: ')) {
          const dataStr = line.slice(6);
          if (dataStr === '[DONE]') continue;

          try {
            const data = JSON.parse(dataStr);
            const delta = data.choices[0]?.delta;
            const content = delta?.content || delta?.reasoning || '';

            if (content) {
              fullContent += content;
              tokenCount += 1; // Simplistic token count
              yield {
                modelId,
                content,
                isDone: false,
              };
            }
          } catch (e) {
            console.error('Error parsing stream chunk', e);
          }
        }
      }
    }

    const duration = Date.now() - startTime;
    const tps = tokenCount / (duration / 1000);

    yield {
      modelId,
      isDone: true,
      metrics: {
        duration,
        tokenCount,
        tps: parseFloat(tps.toFixed(2)),
      },
    };
  } catch (error: any) {
    yield {
      modelId,
      error: error.message,
      isDone: true,
    };
  }
}

import { NextRequest } from 'next/server';
import { evaluateModelStream } from '@/lib/evaluator';
import { getSettings } from '@/lib/storage';
import { Message } from '@/lib/types';

export async function POST(req: NextRequest) {
  const { modelId, messages } = await req.json();
  const settings = await getSettings();

  const stream = new ReadableStream({
    async start(controller) {
      const generator = evaluateModelStream(modelId, messages as Message[], settings);

      for await (const chunk of generator) {
        controller.enqueue(new TextEncoder().encode(JSON.stringify(chunk) + '\n'));
      }
      controller.close();
    },
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'application/x-ndjson',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
    },
  });
}

'use client';

import React from 'react';
import { ModelResponse } from '@/lib/types';
import { Timer, Zap, Hash, AlertCircle } from 'lucide-react';

interface ModelContainerProps {
  modelId: string;
  modelName: string;
  response?: ModelResponse;
  isStreaming: boolean;
  content: string;
}

export const ModelContainer: React.FC<ModelContainerProps> = ({
  modelId,
  modelName,
  response,
  isStreaming,
  content,
}) => {
  return (
    <div className="flex flex-col h-full bg-mocha-mantle border border-mocha-surface1 rounded-xl overflow-hidden shadow-lg">
      <div className="p-3 bg-mocha-surface0 border-b border-mocha-surface1 flex items-center justify-between">
        <h3 className="font-bold text-mocha-lavender truncate">{modelName}</h3>
        {isStreaming && (
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 bg-mocha-blue rounded-full animate-pulse" />
            <span className="text-xs text-mocha-subtext0">Streaming...</span>
          </div>
        )}
      </div>

      <div className="flex-1 p-4 overflow-y-auto font-sans text-mocha-text whitespace-pre-wrap">
        {content || (isStreaming ? '' : <span className="text-mocha-surface2 italic">Awaiting prompt...</span>)}
        {response?.error && (
          <div className="mt-2 p-3 bg-mocha-red/10 border border-mocha-red/20 rounded-md text-mocha-red text-sm flex items-start gap-2">
            <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <span>{response.error}</span>
          </div>
        )}
      </div>

      {response && !isStreaming && (
        <div className="p-3 bg-mocha-crust border-t border-mocha-surface1 flex flex-wrap gap-4 text-[10px] text-mocha-subtext1">
          <div className="flex items-center gap-1.5">
            <Timer className="w-3 h-3 text-mocha-blue" />
            <span>{(response.duration / 1000).toFixed(2)}s</span>
          </div>
          <div className="flex items-center gap-1.5">
            <Zap className="w-3 h-3 text-mocha-yellow" />
            <span>{response.tps} TPS</span>
          </div>
          <div className="flex items-center gap-1.5">
            <Hash className="w-3 h-3 text-mocha-green" />
            <span>{response.tokenCount} chars</span>
          </div>
        </div>
      )}
    </div>
  );
};

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Model, ModelResponse, Settings, Message } from '@/lib/types';
import { ModelContainer } from './ModelContainer';
import { Button } from './ui/Button';
import { Send, Trash2, Download, Copy, Check } from 'lucide-react';
import { saveConversation } from '@/lib/storage'; // Note: This is server-side usually, I'll need an action

interface ChatInterfaceProps {
  models: Model[];
  selectedModelIds: string[];
  settings: Settings;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({
  models,
  selectedModelIds,
  settings,
}) => {
  const [prompt, setPrompt] = useState('');
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [modelContents, setModelContents] = useState<Record<string, string>>({});
  const [modelResponses, setModelResponses] = useState<Record<string, ModelResponse>>({});
  const [streamingModels, setStreamingModels] = useState<Set<string>>(new Set());
  const [copied, setCopied] = useState(false);

  const selectedModels = models.filter((m) => selectedModelIds.includes(m.id));

  const handleSend = async () => {
    if (!prompt.trim() || isEvaluating) return;

    setIsEvaluating(true);
    setModelContents({});
    setModelResponses({});
    const newStreamingModels = new Set(selectedModelIds);
    setStreamingModels(newStreamingModels);

    const messages: Message[] = [{ role: 'user', content: prompt }];

    // Trigger evaluations in parallel
    const evalPromises = selectedModelIds.map(async (modelId) => {
      try {
        const response = await fetch('/api/evaluate', {
          method: 'POST',
          body: JSON.stringify({ modelId, messages }),
        });

        if (!response.ok) throw new Error('Failed to start evaluation');

        const reader = response.body?.getReader();
        if (!reader) return;

        const decoder = new TextDecoder();
        let buffer = '';

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (!line.trim()) continue;
            try {
              const chunk = JSON.parse(line);
              if (chunk.content) {
                setModelContents((prev) => ({
                  ...prev,
                  [modelId]: (prev[modelId] || '') + chunk.content,
                }));
              }
              if (chunk.isDone) {
                if (chunk.metrics) {
                  setModelResponses((prev) => ({
                    ...prev,
                    [modelId]: {
                      modelId,
                      content: modelContents[modelId] || '',
                      ...chunk.metrics,
                    },
                  }));
                } else if (chunk.error) {
                  setModelResponses((prev) => ({
                    ...prev,
                    [modelId]: {
                      modelId,
                      content: modelContents[modelId] || '',
                      error: chunk.error,
                      duration: 0,
                      tps: 0,
                      tokenCount: 0,
                    },
                  }));
                }
                setStreamingModels((prev) => {
                  const next = new Set(prev);
                  next.delete(modelId);
                  return next;
                });
              }
            } catch (e) {
              console.error('Error parsing chunk', e);
            }
          }
        }
      } catch (error: any) {
        setModelResponses((prev) => ({
          ...prev,
          [modelId]: {
            modelId,
            content: '',
            error: error.message,
            duration: 0,
            tps: 0,
            tokenCount: 0,
          },
        }));
        setStreamingModels((prev) => {
          const next = new Set(prev);
          next.delete(modelId);
          return next;
        });
      }
    });

    await Promise.all(evalPromises);
    setIsEvaluating(false);
  };

  const handleExport = () => {
    const data = {
      prompt,
      timestamp: new Date().toISOString(),
      results: selectedModels.map((m) => ({
        model: m.name,
        modelId: m.id,
        ...modelResponses[m.id],
      })),
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `evaluation-${new Date().getTime()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleCopy = () => {
    const data = {
      prompt,
      results: selectedModels.map((m) => ({
        model: m.name,
        content: modelContents[m.id],
        metrics: modelResponses[m.id],
      })),
    };
    navigator.clipboard.writeText(JSON.stringify(data, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex flex-col h-full space-y-4">
      <div className="flex-1 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4 min-h-0">
        {selectedModelIds.length > 0 ? (
          selectedModelIds.map((modelId) => {
            const model = models.find((m) => m.id === modelId);
            return (
              <ModelContainer
                key={modelId}
                modelId={modelId}
                modelName={model?.name || modelId}
                content={modelContents[modelId] || ''}
                response={modelResponses[modelId]}
                isStreaming={streamingModels.has(modelId)}
              />
            );
          })
        ) : (
          <div className="col-span-full flex items-center justify-center border-2 border-dashed border-mocha-surface1 rounded-xl text-mocha-surface2">
            Select up to 5 models to start evaluation
          </div>
        )}
