const finalResponses: Record<string, ModelResponse> = {};

// Trigger evaluations in parallel
const evalPromises = selectedModelIds.map(async (modelId) => {
  try {
    const response = await fetch('/api/evaluate', {
      method: 'POST',
      body: JSON.stringify({ modelId, messages }),
    });

    if (!response.ok) throw new Error('Failed to start evaluation');

    const reader = response.body?.getReader();
    if (!reader) return;

    const decoder = new TextDecoder();
    let buffer = '';
    let currentContent = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (!line.trim()) continue;
        try {
          const chunk = JSON.parse(line);
          if (chunk.content) {
            currentContent += chunk.content;
            setModelContents((prev) => ({
              ...prev,
              [modelId]: (prev[modelId] || '') + chunk.content,
            }));
          }
          if (chunk.isDone) {
            if (chunk.metrics) {
              const modelRes = {
                modelId,
                content: currentContent,
                ...chunk.metrics,
              };
              finalResponses[modelId] = modelRes;
              setModelResponses((prev) => ({
                ...prev,
                [modelId]: modelRes,
              }));
            } else if (chunk.error) {
              const errorRes = {
                modelId,
                content: currentContent,
                error: chunk.error,
                duration: 0,
                tps: 0,
                tokenCount: 0,
              };
              finalResponses[modelId] = errorRes;
              setModelResponses((prev) => ({
                ...prev,
                [modelId]: errorRes,
              }));
            }
            setStreamingModels((prev) => {
              const next = new Set(prev);
              next.delete(modelId);
              return next;
            });
          }
        } catch (e) {
          console.error('Error parsing chunk', e);
        }
      }
    }
  } catch (error: any) {
    const errRes = {
      modelId,
      content: '',
      error: error.message,
      duration: 0,
      tps: 0,
      tokenCount: 0,
    };
    finalResponses[modelId] = errRes;
    setModelResponses((prev) => ({
      ...prev,
      [modelId]: errRes,
    }));
    setStreamingModels((prev) => {
      const next = new Set(prev);
      next.delete(modelId);
      return next;
    });
  }
});

await Promise.all(evalPromises);

// Save conversation to local storage
if (Object.keys(finalResponses).length > 0) {
  await saveConversationAction({
    id: Date.now().toString(),
    timestamp: new Date().toISOString(),
    prompt,
    responses: finalResponses,
  });
}

