                tokenCount: 0,
              };
              finalResponses[modelId] = errorRes;
              setModelResponses((prev) => ({
                ...prev,
                [modelId]: errorRes,
              }));
            }
            setStreamingModels((prev) => {
              const next = new Set(prev);
              next.delete(modelId);
              return next;
            });
          }
        } catch (e) {
          console.error('Error parsing chunk', e);
        }
      }
    }
  } catch (error: any) {
    const errRes = {
      modelId,
      content: '',
      error: error.message,
      duration: 0,
