'use client';

import React from 'react';
import { Conversation, Model } from '@/lib/types';
import { Trophy, Laugh, Meh } from 'lucide-react';

interface FunnyIndexProps {
  models: Model[];
  conversations: Conversation[];
}

export const FunnyIndex: React.FC<FunnyIndexProps> = ({ models, conversations }) => {
  const stats = React.useMemo(() => {
    const modelStats: Record<string, { funny: number; notFunny: number }> = {};

    conversations.forEach((conv) => {
      Object.entries(conv.responses).forEach(([modelId, response]) => {
        if (!modelStats[modelId]) {
          modelStats[modelId] = { funny: 0, notFunny: 0 };
        }
        if (response.rating === 'funny') {
          modelStats[modelId].funny += 1;
        } else if (response.rating === 'not_funny') {
          modelStats[modelId].notFunny += 1;
        }
      });
    });

    return Object.entries(modelStats)
      .map(([modelId, stat]) => {
        const model = models.find((m) => m.id === modelId);
        const total = stat.funny + stat.notFunny;
        const score = total > 0 ? (stat.funny / total) * 100 : 0;
        return {
          id: modelId,
          name: model?.name || modelId,
          funny: stat.funny,
          notFunny: stat.notFunny,
          total,
          score,
        };
      })
      .sort((a, b) => b.score - a.score || b.funny - a.funny);
  }, [models, conversations]);

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="text-center space-y-2">
        <h2 className="text-4xl font-bold text-mocha-text flex items-center justify-center gap-3">
          <Trophy className="w-10 h-10 text-mocha-yellow" />
          The Funny Index
        </h2>
        <p className="text-mocha-subtext1 text-lg">Ranking the world's free LLMs by their Larry David approved humor.</p>
      </div>

      <div className="bg-mocha-mantle border border-mocha-surface1 rounded-2xl overflow-hidden shadow-2xl">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-mocha-surface0 text-mocha-lavender text-sm uppercase tracking-wider">
              <th className="px-6 py-4 font-bold">Rank</th>
              <th className="px-6 py-4 font-bold">Model</th>
              <th className="px-6 py-4 font-bold">Funny Score</th>
              <th className="px-6 py-4 font-bold text-center">Stats</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-mocha-surface1">
            {stats.length > 0 ? (
              stats.map((stat, index) => (
                <tr key={stat.id} className="hover:bg-mocha-surface0/50 transition-colors group">
                  <td className="px-6 py-4">
                    <span className={`
                      inline-flex items-center justify-center w-8 h-8 rounded-full font-bold text-sm
                      ${index === 0 ? 'bg-mocha-yellow text-mocha-base' : 
                        index === 1 ? 'bg-mocha-overlay2 text-mocha-base' :
                        index === 2 ? 'bg-mocha-peach text-mocha-base' :
                        'bg-mocha-surface1 text-mocha-subtext1'}
                    `}>
                      {index + 1}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-mocha-text">{stat.name}</div>
                    <div className="text-[10px] text-mocha-overlay0 font-mono truncate max-w-[200px]">{stat.id}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className="flex-1 h-2 bg-mocha-surface1 rounded-full overflow-hidden min-w-[100px]">
                        <div 
                          className="h-full bg-mocha-green transition-all duration-1000" 
                          style={{ width: `${stat.score}%` }}
                        />
                      </div>
                      <span className="font-mono font-bold text-mocha-green w-12 text-right">
                        {stat.score.toFixed(0)}%
                      </span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center justify-center gap-4">
                      <div className="flex items-center gap-1 text-mocha-green" title="Funny">
                        <Laugh className="w-4 h-4" />
                        <span className="font-bold">{stat.funny}</span>
                      </div>
                      <div className="flex items-center gap-1 text-mocha-red" title="Not Funny">
                        <Meh className="w-4 h-4" />
                        <span className="font-bold">{stat.notFunny}</span>
                      </div>
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={4} className="px-6 py-20 text-center text-mocha-subtext1 italic">
                  No ratings yet. Go to "Tell me a Joke" and start judging!
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import { Model, ModelResponse, Settings, Message } from '@/lib/types';
import { ModelContainer } from './ModelContainer';
import { Button } from './ui/Button';
import { Laugh, Meh, Send, Trash2 } from 'lucide-react';
import { saveConversationAction } from '@/app/actions';

interface JokeInterfaceProps {
  models: Model[];
  selectedModelIds: string[];
  settings: Settings;
  onRandomizeModel: (oldModelId: string) => void;
}

export const JokeInterface: React.FC<JokeInterfaceProps> = ({
  models,
  selectedModelIds,
  settings,
  onRandomizeModel,
}) => {
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [modelContents, setModelContents] = useState<Record<string, string>>({});
  const [modelThinkingContents, setModelThinkingContents] = useState<Record<string, string>>({});
  const [modelResponses, setModelResponses] = useState<Record<string, ModelResponse>>({});
  const [streamingModels, setStreamingModels] = useState<Set<string>>(new Set());
  const [ratings, setRatings] = useState<Record<string, 'funny' | 'not_funny'>>({});

  const selectedModels = models.filter((m) => selectedModelIds.includes(m.id));

  const handleTellJoke = async () => {
    if (isEvaluating || selectedModelIds.length === 0) return;

    setIsEvaluating(true);
    setModelContents({});
    setModelThinkingContents({});
    setModelResponses({});
    setRatings({});
    const newStreamingModels = new Set(selectedModelIds);
    setStreamingModels(newStreamingModels);

    // Prompt is provided by system prompt in joke mode
    const messages: Message[] = [{ role: 'user', content: "Tell me a joke." }];

    // We'll override the system prompt in the API call by passing a special flag or just handling it in actions
    // For now, we'll use a hidden prompt approach or just rely on the server action handling it if we update it.
    // Actually, let's just use the current API but with the joke prompt.

    const finalResponses: Record<string, ModelResponse> = {};

    const evalPromises = selectedModelIds.map(async (modelId) => {
      try {
        const response = await fetch('/api/evaluate', {
          method: 'POST',
          body: JSON.stringify({ 
            modelId, 
            messages,
            isJokeMode: true // We'll handle this in the API route
          }),
        });

        if (!response.ok) throw new Error('Failed to start evaluation');

        const reader = response.body?.getReader();
        if (!reader) return;

        const decoder = new TextDecoder();
        let buffer = '';
        let currentContent = '';
        let currentThinking = '';

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (!line.trim()) continue;
            try {
              const chunk = JSON.parse(line);
              if (chunk.content) {
                currentContent += chunk.content;
                setModelContents((prev) => ({
                  ...prev,
                  [modelId]: (prev[modelId] || '') + chunk.content,
                }));
              }
              if (chunk.thinkingContent) {
                currentThinking += chunk.thinkingContent;
                setModelThinkingContents((prev) => ({
                  ...prev,
                  [modelId]: (prev[modelId] || '') + chunk.thinkingContent,
                }));
              }
              if (chunk.isDone) {
                if (chunk.metrics) {
                  const modelRes = {
                    modelId,
                    content: currentContent,
                    thinkingContent: currentThinking,
                    ...chunk.metrics,
                  };
                  finalResponses[modelId] = modelRes;
                  setModelResponses((prev) => ({
                    ...prev,
                    [modelId]: modelRes,
                  }));
                }
                setStreamingModels((prev) => {
                  const next = new Set(prev);
                  next.delete(modelId);
                  return next;
                });
              }
            } catch (e) {
              console.error('Error parsing chunk', e);
            }
          }
        }
      } catch (error: any) {
        setStreamingModels((prev) => {
          const next = new Set(prev);
          next.delete(modelId);
          return next;
        });
      }
    });

    await Promise.all(evalPromises);
    setIsEvaluating(false);
  };

  const handleRate = async (modelId: string, rating: 'funny' | 'not_funny') => {
    const response = modelResponses[modelId];
    if (!response) return;

    const newResponse = { ...response, rating };

    setRatings(prev => ({ ...prev, [modelId]: rating }));
    setModelResponses(prev => ({ ...prev, [modelId]: newResponse }));

    // Update final responses and save
    const updatedResponses = { ...modelResponses, [modelId]: newResponse };

    await saveConversationAction({
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      prompt: "Tell me a joke (Joke Mode)",
      responses: updatedResponses,
    });
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      <div className="bg-mocha-mantle p-6 border border-mocha-surface1 rounded-2xl shadow-xl text-center space-y-4">
        <h2 className="text-3xl font-bold text-mocha-text flex items-center justify-center gap-3">
          <Laugh className="w-8 h-8 text-mocha-yellow" />
          Larry David Joke Test
        </h2>
        <p className="text-mocha-subtext1 max-w-2xl mx-auto">
          Each model is given the same Larry David approved system prompt. 
          Your job is simple: **Is it funny or not?** Use the buttons on each card to vote.
        </p>
        <Button 
          size="lg" 
          onClick={handleTellJoke} 
          disabled={isEvaluating || selectedModelIds.length === 0}
          className="bg-mocha-yellow hover:bg-mocha-yellow/90 text-mocha-base font-bold px-12 py-6 text-xl rounded-full shadow-lg shadow-mocha-yellow/20"
        >
          {isEvaluating ? 'Models are thinking...' : 'GENERATE JOKES'}
        </Button>
      </div>

      <div className="flex-1 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-7 gap-4 min-h-0">
        {selectedModelIds.length > 0 ? (
          selectedModelIds.map((modelId) => {
            const model = models.find((m) => m.id === modelId);
            const response = modelResponses[modelId];
            const currentRating = ratings[modelId];

            return (
              <div key={modelId} className="flex flex-col gap-3 h-full">
                <ModelContainer
                  modelId={modelId}
                  modelName={model?.name || modelId}
                  content={modelContents[modelId] || ''}
                  thinkingContent={modelThinkingContents[modelId] || ''}
                  response={response}
                  isStreaming={streamingModels.has(modelId)}
                  onRandomize={() => onRandomizeModel(modelId)}
                />
                {response && !streamingModels.has(modelId) && (
                  <div className="flex gap-2 animate-in fade-in slide-in-from-top-2 duration-300">
                    <button
                      onClick={() => handleRate(modelId, 'funny')}
                      disabled={!!currentRating}
                      className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border-2 transition-all font-bold ${
                        currentRating === 'funny' 
                          ? 'bg-mocha-green border-mocha-green text-mocha-base' 
                          : 'bg-mocha-surface0 border-mocha-surface1 text-mocha-green hover:border-mocha-green'
                      } ${currentRating && currentRating !== 'funny' ? 'opacity-30' : ''}`}
                    >
                      <Laugh className="w-5 h-5" />
                      FUNNY
                    </button>
                    <button
                      onClick={() => handleRate(modelId, 'not_funny')}
                      disabled={!!currentRating}
                      className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border-2 transition-all font-bold ${
                        currentRating === 'not_funny' 
                          ? 'bg-mocha-red border-mocha-red text-mocha-base' 
                          : 'bg-mocha-surface0 border-mocha-surface1 text-mocha-red hover:border-mocha-red'
                      } ${currentRating && currentRating !== 'not_funny' ? 'opacity-30' : ''}`}
                    >
                      <Meh className="w-5 h-5" />
                      NOT FUNNY
                    </button>
                  </div>
                )}
              </div>
            );
          })
        ) : (
          <div className="col-span-full flex items-center justify-center border-2 border-dashed border-mocha-surface1 rounded-xl text-mocha-surface2">
            Select some models first to hear some jokes!
          </div>
        )}
      </div>
    </div>
  );
};

