const evaluateSingleModel = async (modelId: string, currentPrompt: string) => {
  if (!currentPrompt.trim()) return;

  // Reset state for this model
  setModelContents(prev => ({ ...prev, [modelId]: '' }));
  setModelThinkingContents(prev => ({ ...prev, [modelId]: '' }));
  setModelResponses(prev => {
    const next = { ...prev };
    delete next[modelId];
    return next;
  });
  setStreamingModels(prev => new Set(prev).add(modelId));

  const messages: Message[] = [{ role: 'user', content: currentPrompt }];

  try {
    const response = await fetch('/api/evaluate', {
      method: 'POST',
      body: JSON.stringify({ modelId, messages }),
    });

    if (!response.ok) throw new Error('Failed to start evaluation');

    const reader = response.body?.getReader();
    if (!reader) return;

    const decoder = new TextDecoder();
    let buffer = '';
    let currentContent = '';
    let currentThinking = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (!line.trim()) continue;
        try {
          const chunk = JSON.parse(line);
          if (chunk.content) {
            currentContent += chunk.content;
            setModelContents((prev) => ({
              ...prev,
              [modelId]: (prev[modelId] || '') + chunk.content,
            }));
          }
          if (chunk.thinkingContent) {
            currentThinking += chunk.thinkingContent;
            setModelThinkingContents((prev) => ({
              ...prev,
              [modelId]: (prev[modelId] || '') + chunk.thinkingContent,
            }));
          }
          if (chunk.isDone) {
            if (chunk.metrics) {
              const modelRes = {
                modelId,
                content: currentContent,
                thinkingContent: currentThinking,
                ...chunk.metrics,
              };
              setModelResponses((prev) => ({
                ...prev,
                [modelId]: modelRes,
              }));
            } else if (chunk.error) {
              const errorRes = {
                modelId,
                content: currentContent,
                thinkingContent: currentThinking,
                error: chunk.error,
                duration: 0,
                tps: 0,
                tokenCount: 0,
              };
              setModelResponses((prev) => ({
                ...prev,
                [modelId]: errorRes,
              }));
            }
            setStreamingModels((prev) => {
              const next = new Set(prev);
              next.delete(modelId);
              return next;
            });
          }
        } catch (e) {
          console.error('Error parsing chunk', e);
        }
      }
    }
  } catch (error: any) {
    const errRes = {
      modelId,
      content: '',
      error: error.message,
      duration: 0,
      tps: 0,
      tokenCount: 0,
    };
    setModelResponses((prev) => ({
      ...prev,
      [modelId]: errRes,
    }));
    setStreamingModels((prev) => {
      const next = new Set(prev);
      next.delete(modelId);
      return next;
    });
  }
};

